import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from './AuthContext';
import './Login.css';

function Login() {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [successMessage, setSuccessMessage] = useState('');
    const { login } = useAuth();
    const navigate = useNavigate();

    const handleLogin = async (e) => {
        e.preventDefault();

        try {
            const response = await fetch('http://localhost:5123/User/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ username, password }),
            });

            const data = await response.json();

            if (response.ok) {
                localStorage.setItem('token', data.token); // Token elmentése
                login(); // Bejelentkezési állapot frissítése
                setSuccessMessage('Sikeres bejelentkezés!');
                setError('');
                setTimeout(() => {
                    navigate('/profile'); // Átirányítás a profil oldalra
                }, 1500);
            } else {
                setError(data.message || 'Hibás felhasználónév vagy jelszó');
                setSuccessMessage('');
            }
        } catch (error) {
            setError('Hiba történt a bejelentkezés során');
            setSuccessMessage('');
        }
    };

    return (
        <div className="login-container">
            <div className="login-box">
                <h2>Bejelentkezés</h2>
                {error && <div className="error-message">{error}</div>}
                {successMessage && <div className="success-message">{successMessage}</div>}
                <form onSubmit={handleLogin}>
                    <div className="form-group">
                        <label htmlFor="username">Felhasználónév</label>
                        <input
                            type="text"
                            id="username"
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            placeholder="Felhasználónév"
                            required
                        />
                    </div>
                    <div className="form-group">
                        <label htmlFor="password">Jelszó</label>
                        <input
                            type="password"
                            id="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="Jelszó"
                            required
                        />
                    </div>
                    <button type="submit" className="btn btn-primary">
                        Bejelentkezés
                    </button>
                </form>
            </div>
        </div>
    );
}

export default Login;
